import { useCallback, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useShallow } from "zustand/react/shallow";
import Alert from "@mui/material/Alert";
import Box from "@mui/material/Box";
import LinearProgress from "@mui/material/LinearProgress";
import Paper from "@mui/material/Paper";
import { parseAsString, useQueryState } from "nuqs";

import { PAGE_PATHS } from "../../routes/paths";
import { useConnectionStore } from "../../store/useConnectionStore";
import { useProfilingFiltersStore } from "../../store/useProfilingFiltersStore";
import { EMPTY_PROFILING_FILTERS } from "../../types/pageFilters";
import EmptyState from "../EmptyState";
import PageInsightBanner from "../PageInsightBanner";
import { INSIGHT_GUARDRAIL } from "../../hooks/insightPromptUtils";
import { findColumnIndex, getRowValue } from "../../services/es/columnUtils";

import { PROFILING_DIMENSION_LABELS, type ProfilingFocusDimension } from "./profilingQueryBuilder";
import { isMissingProfilingIndex } from "./profilingUtils";
import ProfilingFocusPicker from "./ProfilingFocusPicker";
import ProfilingFocusHeader from "./ProfilingFocusHeader";
import ProfilingValuePicker from "./ProfilingValuePicker";
import ProfilingToolbar from "./ProfilingToolbar";
import ProfilingResults from "./ProfilingResults";
import { useProfilingData } from "./useProfilingData";

function isProfilingFocusDimension(value: string | null): value is ProfilingFocusDimension {
  return !!value && Object.prototype.hasOwnProperty.call(PROFILING_DIMENSION_LABELS, value);
}

export default function ProfilingGuidedPage() {
  const navigate = useNavigate();
  const connection = useConnectionStore((state) => state.connection);
  const { expandedStacktraceIds, toggleExpandedStacktraceId } = useProfilingFiltersStore(
    useShallow((s) => ({
      expandedStacktraceIds: s.expandedStacktraceIds,
      toggleExpandedStacktraceId: s.toggleExpandedStacktraceId,
    })),
  );

  // URL-persisted focus state
  const [urlDimension, setUrlDimension] = useQueryState("focus", parseAsString);
  const [urlValue, setUrlValue] = useQueryState("value", parseAsString);

  const isEverything = urlDimension === "";
  const dimension = isProfilingFocusDimension(urlDimension) ? urlDimension : null;
  const value = urlValue ?? null;

  // Time range (local state, not shared with advanced page)
  const [timeFrom, setTimeFrom] = useState(EMPTY_PROFILING_FILTERS.timeFrom);
  const [timeTo, setTimeTo] = useState(EMPTY_PROFILING_FILTERS.timeTo);

  // View mode (flamegraph by default in guided flow)
  const [viewMode, setViewMode] = useState<
    "topFunctions" | "stacktraces" | "timeline" | "flamegraph" | "flamescope"
  >("flamegraph");

  // Track "ready to show results": dimension has been chosen (null = "Everything") and if
  // dimension is non-null, a value must also be set.
  const showResults = (isEverything || dimension !== null) && (isEverything || urlValue !== null);

  const {
    loading,
    error,
    topFunctionsRows,
    timelineResult,
    stacktraces,
    setFlamescopeWindow,
    flamegraphTree,
    handleOpenInQueryLab,
    handleFrameClick,
    hasRun,
    resetResults,
  } = useProfilingData({
    connection,
    viewMode,
    dimension,
    value,
    timeFrom,
    timeTo,
    showResults,
  });

  const handleSelectDimension = useCallback(
    async (dim: ProfilingFocusDimension | null) => {
      if (dim === null) {
        // "Everything" — skip value picker, go straight to results
        await Promise.all([setUrlDimension(""), setUrlValue(null)]);
      } else {
        await Promise.all([setUrlDimension(dim), setUrlValue(null)]);
      }
    },
    [setUrlDimension, setUrlValue],
  );

  const handleSelectValue = useCallback(
    async (val: string) => {
      await setUrlValue(val);
    },
    [setUrlValue],
  );

  const handleChangeFocus = useCallback(async () => {
    resetResults();
    await Promise.all([setUrlDimension(null), setUrlValue(null)]);
  }, [resetResults, setUrlDimension, setUrlValue]);

  const displayDimension = isEverything ? null : dimension;
  const timelineHasData = (timelineResult?.values.length ?? 0) > 0;
  const hasDataForCurrentView =
    viewMode === "topFunctions"
      ? topFunctionsRows.length > 0
      : viewMode === "timeline"
        ? timelineHasData
        : stacktraces.length > 0;
  const canShowProfilingInsights =
    !loading && !error && showResults && hasRun && hasDataForCurrentView;
  const timelineCountStats = useMemo(() => {
    if (!timelineResult) return null;
    const countIdx = findColumnIndex(timelineResult.columns, "count");
    if (countIdx < 0) return null;
    const counts = timelineResult.values
      .map((row) => Number(getRowValue(row, countIdx) ?? 0))
      .filter((v) => Number.isFinite(v));
    if (counts.length === 0) return null;
    return {
      points: counts.length,
      max: Math.max(...counts),
      min: Math.min(...counts),
      avg: counts.reduce((sum, v) => sum + v, 0) / counts.length,
    };
  }, [timelineResult]);

  const profilingInsightContext = useMemo(() => {
    if (!canShowProfilingInsights) return "";
    const topFunctions = topFunctionsRows.slice(0, 10).map((row) => ({
      name: row.functionName,
      total: row.totalCount ?? 0,
      self: row.selfCount ?? 0,
    }));
    const topStacks = stacktraces
      .slice()
      .sort((a, b) => b.count - a.count)
      .slice(0, 10)
      .map((row) => ({
        id: row.stacktraceId,
        count: row.count,
        service: row.serviceName,
        host: row.hostName,
      }));
    return JSON.stringify({
      page: "profiling-guided",
      viewMode,
      focus: {
        dimension: displayDimension,
        value,
      },
      timeRange: {
        from: timeFrom,
        to: timeTo,
      },
      datasets: {
        topFunctions,
        timeline: timelineCountStats,
        stacktraces: topStacks,
        flamegraphNodeCount: flamegraphTree.children.length,
      },
    });
  }, [
    canShowProfilingInsights,
    displayDimension,
    flamegraphTree.children.length,
    stacktraces,
    timeFrom,
    timeTo,
    timelineCountStats,
    topFunctionsRows,
    value,
    viewMode,
  ]);

  // ── Step 1: Focus picker ────────────────────────────────────────────────────
  if (urlDimension === null || (!isEverything && dimension === null)) {
    return <ProfilingFocusPicker onSelect={(dim) => void handleSelectDimension(dim)} />;
  }

  // ── Step 2: Value picker (only if a specific dimension was chosen) ──────────
  if (dimension && urlValue === null && connection) {
    return (
      <ProfilingValuePicker
        dimension={dimension}
        connection={connection}
        timeFrom={timeFrom}
        timeTo={timeTo}
        onTimeRangeChange={(from, to) => {
          setTimeFrom(from);
          setTimeTo(to);
        }}
        onSelect={(val) => void handleSelectValue(val)}
        onBack={() => void handleChangeFocus()}
      />
    );
  }

  // ── Step 3: Results view ────────────────────────────────────────────────────
  return (
    <Box sx={{ display: "flex", flexDirection: "column", gap: 1, minHeight: "100%" }}>
      <ProfilingFocusHeader
        dimension={displayDimension}
        value={value}
        onChangeFocus={() => void handleChangeFocus()}
      />

      <ProfilingToolbar
        timeFrom={timeFrom}
        timeTo={timeTo}
        onTimeChange={(from, to) => {
          setTimeFrom(from);
          setTimeTo(to);
        }}
        viewMode={viewMode}
        onViewModeChange={setViewMode}
        showOpenInQueryLab={viewMode !== "topFunctions"}
        onOpenInQueryLab={handleOpenInQueryLab}
        onAdvancedView={() => navigate(PAGE_PATHS.profilingAdvanced.path)}
      />

      {loading && <LinearProgress />}

      {error && !isMissingProfilingIndex(error) && <Alert severity="error">{error}</Alert>}
      {error && isMissingProfilingIndex(error) && (
        <Paper variant="outlined" sx={{ flex: 1, minHeight: 320, overflow: "auto" }}>
          <EmptyState
            heading="No profiling data available"
            description="The profiling-events data stream was not found. Enable Universal Profiling in your Elastic cluster to start collecting continuous profiling data."
          />
        </Paper>
      )}

      {!(error && isMissingProfilingIndex(error)) && (
        <>
          {canShowProfilingInsights && profilingInsightContext && (
            <PageInsightBanner
              context={profilingInsightContext}
              systemPrompt={
                "You are a profiling performance analyst. Summarize the active profiling dataset and " +
                "highlight one non-obvious hotspot, skew, or next debugging step." +
                INSIGHT_GUARDRAIL
              }
              cacheKey={`profiling-guided::${profilingInsightContext}`}
            />
          )}
          <ProfilingResults
            loading={loading}
            hasRun={hasRun}
            error={error}
            viewMode={viewMode}
            topFunctionsRows={topFunctionsRows}
            timelineResult={timelineResult}
            stacktraces={stacktraces}
            flamegraphTree={flamegraphTree}
            onFlamescopeWindowChange={setFlamescopeWindow}
            handleFrameClick={handleFrameClick}
            expandedStacktraceIds={expandedStacktraceIds}
            toggleExpandedStacktraceId={toggleExpandedStacktraceId}
          />
        </>
      )}
    </Box>
  );
}
